{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatherapy for Everyday Ritual</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="brand">
        <svg class="brand-mark" viewBox="0 0 64 64" aria-hidden="true">
          <defs>
            <linearGradient id="g1" x1="0" x2="1">
              <stop offset="0" stop-color="#9be7c4"/>
              <stop offset="1" stop-color="#6ec1ff"/>
            </linearGradient>
          </defs>
          <circle cx="32" cy="32" r="30" fill="url(#g1)" opacity="0.12"/>
          <path d="M18 38c8-12 22-12 30-6-6 8-18 14-30 6z" fill="#fff" opacity="0.9"/>
        </svg>
        <div class="brand-text">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="sub">{{TAGLINE}}</p>
        </div>
      </div>
      <nav class="nav" aria-label="Primary">
        <button class="nav-toggle" aria-expanded="false">☰</button>
        <ul class="nav-list">
          <li><a href="index.html">Home</a></li>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="blends.html">Blends</a></li>
          <li><a href="shop.html">Boutique</a></li>
          <li><a href="about.html">Our Story</a></li>
          <li><a href="book.html">Reserve</a></li>
          <li><a href="contact.html">Reach Out</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <img src="assets/img/pattern.svg" class="hero-pattern" alt="decorative pattern" aria-hidden="true">
      <div class="hero-inner">
        <h2 class="eyebrow">A gentle approach to scent</h2>
        <h1 class="hero-title">Rituals that speak in scent — crafted by {{PRACTITIONER_NAME}}</h1>
        <p class="lead">Blends, consultations, and approachable education to bring calm, clarity, and seasonal joy into your everyday routines. Safety-forward and tailored for you.</p>
        <p class="hero-cta"><a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a> <a class="btn ghost" href="book.html">Book a consult</a></p>
        <p class="local">Serving {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section id="diagnostic" class="panel diagnostic">
      <div class="container">
        <h3>Find a scent direction — quick aroma diagnostic</h3>
        <p class="muted">This short quiz helps identify scent families and gentle blends that might suit your preferences. This is educational — not medical advice. Always patch test and follow dilution guidance.</p>
        <form id="quiz" class="quiz">
          <fieldset>
            <legend>Which notes do you lean toward?</legend>
            <label><input type="checkbox" name="notes" value="citrus"> Bright citrus (lemon, bergamot)</label>
            <label><input type="checkbox" name="notes" value="floral"> Soft floral (lavender, ylang-ylang)</label>
            <label><input type="checkbox" name="notes" value="herbal"> Herbal & green (rosemary, basil)</label>
            <label><input type="checkbox" name="notes" value="wood"> Warm woods (cedarwood, sandalwood)</label>
          </fieldset>

          <fieldset>
            <legend>Experience notes</legend>
            <label><input type="checkbox" name="experience" value="focus"> I want better focus</label>
            <label><input type="checkbox" name="experience" value="sleep"> Help winding down</label>
            <label><input type="checkbox" name="experience" value="uplift"> Uplift mood</label>
            <label><input type="checkbox" name="experience" value="calm"> Reduce stress/tension</label>
          </fieldset>

          <div class="safety">
            <strong>Safety notes:</strong> Avoid claims of diagnosis or cure. Do a patch test, dilute appropriately, and consult your healthcare provider if pregnant, nursing, or on medication. See our FAQ for dilution and pet safety.
          </div>

          <p class="form-actions"><button type="submit" class="btn primary">Reveal a gentle suggestion</button> <button type="button" id="clear" class="btn ghost">Clear</button></p>
        </form>

        <div id="quiz-result" class="result" aria-live="polite"></div>
      </div>
    </section>

    <!-- PLAN -->
    <section id="plan" class="panel plan">
      <div class="container">
        <h3>Your simple plan</h3>
        <p class="muted">A three-step introductory pathway to integrate aromatherapy safely and enjoyably.</p>
        <div class="cards grid">
          <article class="card">
            <h4>1. Consult</h4>
            <p>15–30 min intake to discuss preferences, sensitivities, and lifestyle so blends are safe and personal.</p>
          </article>
          <article class="card">
            <h4>2. Custom blend</h4>
            <p>A gentle, low-dilution blend you can use as a roll-on or in a diffuser. Botanical names and dilution percent included.</p>
          </article>
          <article class="card">
            <h4>3. Follow-up</h4>
            <p>A short check-in to refine the blend and adjust usage guidance for seasonal changes or new needs.</p>
          </article>
        </div>
        <p class="muted small">All plans emphasize safety: dilution, patch tests, and pet/pregnancy considerations are discussed during consults.</p>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section id="micro_habits" class="panel micro">
      <div class="container">
        <h3>Micro-habits to layer with scent</h3>
        <p class="muted">Tiny daily rituals that pair with aroma for approachable wellbeing. Start small — 1–5 minutes each day.</p>
        <ul class="habits grid">
          <li><strong>Morning mist:</strong> 3–4 spray room blend to set intention.</li>
          <li><strong>Roll-on pocket:</strong> 1–2 gentle swipes on wrists for commute calm.</li>
          <li><strong>Diffuser focus:</strong> 15–30 min during concentrated work sessions.</li>
          <li><strong>Evening inhale:</strong> 2–3 slow inhales from a handkerchief before bed.</li>
        </ul>
        <p class="small muted">Tip: Record responses in a scent journal — scent memory is personal. Reduce frequency if sensitivity develops.</p>
      </div>
    </section>

    <!-- PRICING -->
    <section id="pricing" class="panel pricing">
      <div class="container">
        <h3>Retail & service pricing</h3>
        <p class="muted">Transparent pricing for mixtures, consults, and starter kits. All blends come with dilution notes and usage guidance.</p>
        <div class="cards grid pricing-grid">
          <article class="card">
            <h4>Starter Roll-on</h4>
            <p class="price">$18</p>
            <p>Pre-blended 10ml roll-on. Ready for on-the-go support.</p>
            <p><a class="btn" href="shop.html">View</a></p>
          </article>
          <article class="card featured">
            <h4>Personal Consultation</h4>
            <p class="price">$65</p>
            <p>30-min consult with personalized blend and follow-up notes.</p>
            <p><a class="btn primary" href="book.html">Book</a></p>
          </article>
          <article class="card">
            <h4>Starter Diffuser Kit</h4>
            <p class="price">$95</p>
            <p>Mini diffuser + 3 pre-made blends and a guide to safe use.</p>
            <p><a class="btn" href="shop.html">Shop</a></p>
          </article>
        </div>
        <p class="muted small">Need a custom quote? <a href="contact.html">Get in touch</a>.</p>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section class="panel cta-panel">
      <div class="container cta-inner">
        <h3>Ready to try a tailored blend?</h3>
        <p>Schedule a friendly consult with {{PRACTITIONER_NAME}} to craft a safe and personalized aroma practice.</p>
        <p><a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        <p class="muted small">Questions first? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <h4>{{BUSINESS_NAME}}</h4>
        <p>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav>
        <h5>Explore</h5>
        <ul>
          <li><a href="index.html">Home</a></li>
          <li><a href="blends.html">Blends</a></li>
          <li><a href="shop.html">Shop</a></li>
          <li><a href="book.html">Book</a></li>
        </ul>
      </nav>
      <div>
        <h5>Practitioner</h5>
        <p>{{PRACTITIONER_NAME}}</p>
        <p class="muted small">Safety-forward aromatherapy: dilution, patch test, and pet/pregnancy guidance provided.</p>
      </div>
    </div>
    <p class="credit">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved</p>
  </footer>
</body>
</html>"} 
