{"path":"assets/css/styles.css","content":"/* Bold Playful / Mystic Modern palette */
:root{
  --bg:#fbfdfa;--muted:#6b6b6b;--accent1:#6ec1ff;--accent2:#9be7c4;--ink:#122;--card:#fff;--glass:rgba(255,255,255,0.7);
  --radius:12px;--max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;line-height:1.4;color:var(--ink);background:linear-gradient(180deg,var(--bg),#f6fbff);}
.container{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(90deg, rgba(110,193,255,0.08), rgba(155,231,196,0.04));backdrop-filter: blur(6px);border-bottom:1px solid rgba(18,34,34,0.04)}
.header-inner{display:flex;align-items:center;justify-content:space-between;max-width:var(--max-width);margin:0 auto;padding:1rem}
.brand{display:flex;gap:12px;align-items:center}
.brand-mark{width:54px;height:54px}
.brand-text h1{font-size:1.05rem;margin:0;color:var(--ink);letter-spacing:0.6px}
.brand-text .sub{margin:0;font-size:0.85rem;color:var(--muted)}
.nav{position:relative}
.nav-toggle{display:none;background:none;border:0;font-size:1.4rem}
.nav-list{display:flex;gap:18px;list-style:none;margin:0;padding:0}
.nav-list a{text-decoration:none;color:var(--ink);padding:8px;border-radius:8px}
.nav-list a:hover{background:var(--glass)}

/* HERO */
.hero{position:relative;overflow:hidden;padding:4rem 0 6rem;background:linear-gradient(180deg, rgba(158,226,194,0.08), rgba(110,193,255,0.02));}
.hero-pattern{position:absolute;right:-10%;top:-5%;width:60%;opacity:0.7;transform:rotate(6deg)}
.hero-inner{max-width:880px;margin:0 auto;padding:3rem 1rem}
.eyebrow{color:var(--muted);margin:0 0 0.6rem}
.hero-title{font-size:2.2rem;margin:0 0 0.6rem}
.lead{margin:0 0 1rem;color:var(--muted)}
.hero-cta .btn{margin-right:0.6rem}
.local{margin-top:0.8rem;color:var(--muted)}

/* Panels */
.panel{padding:3rem 0;border-top:1px solid rgba(18,34,34,0.03)}
.panel .container{padding:0}
h3{font-size:1.25rem;margin:0 0 0.6rem}
.muted{color:var(--muted)}
.small{font-size:0.9rem}

/* Cards and grids */
.grid{display:grid;gap:16px}
.cards.grid{grid-template-columns:repeat(3,1fr)}
.card{background:var(--card);padding:1.2rem;border-radius:var(--radius);box-shadow:0 6px 18px rgba(18,34,34,0.04)}
.card.featured{transform:translateY(-6px);border:2px solid rgba(110,193,255,0.12)}
.card h4{margin:0 0 8px}
.price{font-weight:700;font-size:1.1rem;margin:0 0 8px}

/* Diagnostic form */
.quiz fieldset{border:0;padding:0;margin:0 0 1rem}
.quiz label{display:block;margin:6px 0}
.safety{background:linear-gradient(90deg, rgba(155,231,196,0.06), rgba(110,193,255,0.03));padding:0.8rem;border-radius:8px;margin:0.6rem 0;color:var(--muted)}
.form-actions{margin-top:0.6rem}
.result{margin-top:1rem;padding:1rem;border-radius:8px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.9));box-shadow:0 6px 18px rgba(18,34,34,0.03)}

/* micro habits */
.habits.grid{grid-template-columns:repeat(2,1fr);gap:12px;list-style:none;padding:0}
.habits li{background:var(--card);padding:12px;border-radius:10px}

/* Pricing */
.pricing-grid{grid-template-columns:repeat(3,1fr)}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;border:1px solid rgba(18,34,34,0.06);background:transparent;color:var(--ink)}
.btn.primary{background:linear-gradient(90deg,var(--accent2),var(--accent1));color:#072;box-shadow:0 8px 20px rgba(110,193,255,0.12);border:none}
.btn.ghost{background:transparent;border:1px solid rgba(18,34,34,0.06)}
.btn.large{padding:14px 20px;font-size:1.05rem}

/* CTA */
.cta-panel{background:linear-gradient(90deg, rgba(155,231,196,0.06), rgba(110,193,255,0.04));text-align:center;border-top:2px solid rgba(18,34,34,0.02)}
.cta-inner{padding:2.2rem}

/* Footer */
.site-footer{margin-top:2rem;padding:2rem 0;background:#fff;border-top:1px solid rgba(18,34,34,0.03)}
.footer-grid{display:grid;grid-template-columns:1fr 160px 1fr;gap:1rem}
.credit{text-align:center;color:var(--muted);margin-top:1rem}

/* Responsive */
@media (max-width:880px){
  .cards.grid{grid-template-columns:1fr}
  .pricing-grid{grid-template-columns:1fr}
  .nav-list{display:none;position:absolute;right:0;top:48px;background:var(--card);padding:12px;border-radius:10px;box-shadow:0 8px 20px rgba(18,34,34,0.06)}
  .nav-toggle{display:inline-block}
  .hero-inner{padding:2rem 1rem}
  .habits.grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // year
  const y=document.getElementById('year'); if(y) y.textContent=(new Date()).getFullYear();

  // nav toggle
  const t=document.querySelector('.nav-toggle'); const list=document.querySelector('.nav-list');
  if(t){t.addEventListener('click',function(){
    const expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', String(!expanded));
    if(list) list.style.display = expanded ? 'none' : 'flex';
  });
  }

  // simple diagnostic
  const quiz=document.getElementById('quiz'); const result=document.getElementById('quiz-result');
  if(quiz){
    quiz.addEventListener('submit',function(e){
      e.preventDefault();
      const data=new FormData(quiz);
      const notes = data.getAll('notes');
      const experience = data.getAll('experience');
      // rudimentary mapping for UX only
      let profile=[];
      if(notes.includes('citrus')) profile.push('Bright Citrus');
      if(notes.includes('floral')) profile.push('Soft Floral');
      if(notes.includes('herbal')) profile.push('Herbal & Green');
      if(notes.includes('wood')) profile.push('Warm Woods');

      let focus=false,sleep=false,uplift=false,calm=false;
      focus = experience.includes('focus'); sleep = experience.includes('sleep'); uplift = experience.includes('uplift'); calm = experience.includes('calm');

      // decide gentle suggestion
      let suggestion='A gentle blend to explore: ' + '{{FAVORITE_BLEND}}' + '.';
      if(profile.length){ suggestion = 'Scent family hint: ' + profile.join(', ') + '. Recommended gentle starting blend: {{FAVORITE_BLEND}}.'; }
      if(sleep) suggestion += ' Use only low dilution (≤1%) for bedtime and patch test first.';
      if(focus) suggestion += ' Try short diffuser bursts (15–30 min) during focused work.';
      if(uplift) suggestion += ' Add citrus top-notes for a bright lift.';
      if(calm) suggestion += ' Include 1–2 drops of lavender in a 10ml roll-on for soothing effect.';

      // safety reminder appended
      suggestion += '\n\nSafety: This is educational guidance. Do a patch test, follow dilution notes, and consult a practitioner if pregnant, nursing, or medicated. Not a medical diagnosis.';

      result.textContent = suggestion;
      result.scrollIntoView({behavior:'smooth',block:'center'});
    });
    const clear=document.getElementById('clear'); if(clear){clear.addEventListener('click',function(){quiz.reset();result.textContent='';});}
  }

  // simple anchor fallback for primary CTA
  const cta=document.querySelectorAll('a[href="{{PRIMARY_CTA_URL}}"]');
  cta.forEach(function(a){a.addEventListener('click',function(e){ /* placeholder for analytics or modal */ });});
});"} 
